CREATE OR REPLACE FUNCTION transfer_funds(from_id INT, to_id INT, amt NUMERIC) RETURNS VOID AS $$
DECLARE
  from_balance NUMERIC;
BEGIN
  -- Lock both rows in a consistent order to avoid deadlocks
  IF from_id < to_id THEN
    SELECT balance INTO from_balance FROM accounts WHERE account_id = from_id FOR UPDATE;
    PERFORM 1 FROM accounts WHERE account_id = to_id FOR UPDATE;
  ELSE
    PERFORM 1 FROM accounts WHERE account_id = to_id FOR UPDATE;
    SELECT balance INTO from_balance FROM accounts WHERE account_id = from_id FOR UPDATE;
  END IF;

  IF from_balance IS NULL THEN
    RAISE EXCEPTION 'Source account % not found', from_id;
  END IF;

  IF from_balance < amt THEN
    RAISE EXCEPTION 'Insufficient funds in account %: balance=%', from_id, from_balance;
  END IF;

  UPDATE accounts SET balance = balance - amt WHERE account_id = from_id;
  UPDATE accounts SET balance = balance + amt WHERE account_id = to_id;
END;
$$ LANGUAGE plpgsql;

-- Example call:
SELECT transfer_funds(1, 2, 300.00);
